// The committed WASM must reproduce the regression goldens (generated by the native CLI)
// bit for bit: same inputs, same results, whatever the platform.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { initSync, Solver } from '../../../public/wasm/solver_wasm.js';

const root = (p: string) => fileURLToPath(new URL(`../../../../${p}`, import.meta.url));
initSync({ module: readFileSync(root('web/public/wasm/solver_wasm_bg.wasm')) });

type Golden = { name: string; spot: unknown; iterations: number; fingerprint: string; evBb: [number, number] };
const goldens = JSON.parse(readFileSync(root('data/goldens/river.json'), 'utf8')).spots as Golden[];

describe('WASM reproduces the native regression goldens', () => {
  for (const g of goldens) {
    it(g.name, () => {
      const s = new Solver(JSON.stringify(g.spot), 1e9);
      s.step(g.iterations);
      expect(s.fingerprint()).toBe(g.fingerprint);
      const ex = JSON.parse(s.exploitability());
      expect(ex.evBb[0]).toBeCloseTo(g.evBb[0], 9);
      s.free();
    });
  }
});
